'use strict';
// Display names stay separate from stable saved race/theme identifiers.
const RACE_DISPLAY_NAMES={Terran:'Helion',Cathaar:'Velari',Xandathrii:'Nexari',Zikonian:'Kryth',Eitraides:'Auralis'};
const THEME_DISPLAY_NAMES={Classic:'Classic',NyanCat:'Nyan Cat',Neutral:'Vesper Command',Terran:'Helion Ascendancy',Cathaar:'Velari Ember',Xandathrii:'Nexari Swarm',Zikonian:'Kryth Frost',Eitraides:'Auralis Tide',LCARS:'Stellar Federation',Borg:'Assimilation Nexus',Stargate:'Gatebound Legacy',DoctorWho:'Temporal Voyager',Battlestar:'Colonial Vanguard'};
function renamedDisplayText(value){let result=String(value).replace(/\b(?:Current )?Round setup\b/gi,'Current Round Setup').replace(/\bRound stats\b/gi,'Stats Editor').replace(/Neutral · COMMAND SKIN/g,'Vesper Command · COMMAND SKIN').replace(/Administration → Planets/g,'Administration → Planet Editor').replace(/Administration → Ship Stats/g,'Administration → Stats Editor');for(const [oldName,name] of Object.entries({'Neutral sci-fi':'Vesper Command','Star Trek LCARS':'Stellar Federation','Star Trek Borg':'Assimilation Nexus','Battlestar Galactica':'Colonial Vanguard','Doctor Who':'Temporal Voyager',Stargate:'Gatebound Legacy','the Miday array':'Satelite Uplink','The Miday array':'Satelite Uplink','Miday array':'Satelite Uplink','Miday Array':'Satelite Uplink','Miday':'Satelite Uplink','Galaxy Status':'Network Hub','Galaxy status':'Network Hub','galaxy status':'network hub','News log':'Journal','News Log':'Journal','news log':'journal',Quests:'Achievements',quests:'achievements',Quest:'Achievement',quest:'achievement',...RACE_DISPLAY_NAMES})){result=result.replace(new RegExp('\\b'+oldName+'\\b','g'),name).replace(new RegExp('\\b'+oldName.toUpperCase()+'\\b','g'),name.toUpperCase());}return result;}
function coordinateDisplayText(value){if(/\d{1,4}[\/-]\d{1,2}[\/-]\d{1,4}/.test(value))return value;return String(value).replace(/\b(\d{1,3})\s*:\s*(\d{1,3})\s*:\s*(\d{1,2})\b/g,(raw,x,y,z)=>Number(x)>=1&&Number(x)<=100&&Number(y)>=1&&Number(y)<=100&&Number(z)>=1&&Number(z)<=15?[x,y,z].map(Number).join(':'):raw).replace(/(GALAXY\s+)(\d{1,3})\s*:\s*(\d{1,3})/gi,(_,label,x,y)=>label+Number(x)+':'+Number(y));}
function applyDisplayNames(root){if(root.nodeType===3){const admin=root.parentElement?.closest('button[data-page="adminPlanets"],button[data-page="adminShips"]');if(admin){const label=admin.dataset.page==='adminPlanets'?'Planet Editor':'Stats Editor';if(root.nodeValue.trim()&&root.parentElement.tagName!=='EM'){if(root.nodeValue!==label)root.nodeValue=label;return;}}if(root.parentElement?.tagName==='OPTION'){applyDisplayNames(root.parentElement);return;}if(!root.parentElement?.closest('script,style,textarea,code,input')){const renamed=renamedDisplayText(root.nodeValue),updated=root.parentElement?.closest('time,.command-time-box,.tickbox,#militaryClock,#serverMilitaryClock')?renamed:coordinateDisplayText(renamed);if(updated!==root.nodeValue)root.nodeValue=updated;}return;}if(root.nodeType!==1&&root.nodeType!==9)return;if(root.nodeType===1){if(root.tagName==='OPTION'){if(!root.hasAttribute('value'))root.setAttribute('value',root.value);const key=root.value,theme=['portalTheme','profileTheme','skinRaceSelect'].includes(root.parentElement?.id),label=theme?THEME_DISPLAY_NAMES[key]:RACE_DISPLAY_NAMES[key];if(label&&root.textContent!==label)root.textContent=label;else if(!label)root.textContent=coordinateDisplayText(root.textContent);return;}if(root.matches('script,style,textarea,code,input'))return;for(const attr of ['alt','title','aria-label'])if(root.hasAttribute(attr)){const old=root.getAttribute(attr),updated=renamedDisplayText(old);if(old!==updated)root.setAttribute(attr,updated);}}for(const child of root.childNodes)applyDisplayNames(child);}
function startDisplayNames(){applyDisplayNames(document.body);new MutationObserver(records=>{for(const record of records){if(record.type==='characterData')applyDisplayNames(record.target);else for(const node of record.addedNodes)applyDisplayNames(node);}}).observe(document.body,{childList:true,subtree:true,characterData:true});document.title=renamedDisplayText(document.title);}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',startDisplayNames);else startDisplayNames();
